using System;
using System.Collections.Generic;

namespace Eggnog.Relations.Benchmarks
{

    /// <summary>
    /// A sequence of inserts and removals against a table with <see cref="KeyCount"/> key columns and
    /// <see cref="ColumnCount"/> columns: the <c>Vec&lt;Operation&lt;3, 5&gt;&gt;</c> of egglog's
    /// <c>core-relations/benches/writes.rs</c>, generated by the same algorithm (<see cref="Generate"/>).
    /// </summary>
    /// <remarks>
    /// Operation <c>i</c> occupies <see cref="Cells"/>[<c>i * ColumnCount</c>, <c>(i + 1) * ColumnCount</c>): a whole row
    /// for an insert, or the key in the first <see cref="KeyCount"/> cells for a removal (<see cref="IsRemoval"/>), so
    /// the key of any operation is its first <see cref="KeyCount"/> cells, as egglog's <c>Operation::key</c>. A flat
    /// array keeps the staging loop free of indirections, as egglog's <c>Vec</c> of inline enums does.
    /// </remarks>
    internal sealed class WritesWorkload
    {

        /// <summary>
        /// The number of key columns (egglog's <c>K = 3</c>).
        /// </summary>
        public const int KeyCount = 3;

        /// <summary>
        /// The number of columns (egglog's <c>C = 5</c>).
        /// </summary>
        public const int ColumnCount = 5;

        /// <summary>
        /// Initializes a new instance over generated operations.
        /// </summary>
        /// <param name="cells">The operations' cells, row-major.</param>
        /// <param name="isRemoval">Whether each operation is a removal.</param>
        WritesWorkload(uint[] cells, bool[] isRemoval)
        {
            Cells = cells;
            IsRemoval = isRemoval;
        }

        /// <summary>
        /// Gets the number of operations.
        /// </summary>
        public int Count => IsRemoval.Length;

        /// <summary>
        /// Gets the cells of every operation, <see cref="ColumnCount"/> per operation.
        /// </summary>
        public uint[] Cells { get; }

        /// <summary>
        /// Gets, for each operation, whether it removes a key (<c>true</c>) or inserts a row (<c>false</c>).
        /// </summary>
        public bool[] IsRemoval { get; }

        /// <summary>
        /// Generates <paramref name="count"/> operations: egglog's <c>generate_workload</c>. Each operation is a removal
        /// with probability <c>1 - <paramref name="insertFraction"/></c>, always of the key of an earlier operation
        /// (egglog removals come from reads of the table); otherwise an insert of a random row, whose key is copied from
        /// an earlier operation with probability <paramref name="collisionFraction"/>. Cells are uniform in
        /// [0, <see cref="uint.MaxValue"/>): <see cref="uint.MaxValue"/> is the stale marker. O(count).
        /// </summary>
        /// <remarks>
        /// egglog draws from <c>rand::rng()</c>, seeded from the OS on every run; this draws from a seeded
        /// <see cref="Random"/> so that every thread count, process and run sees the same operations. The two random
        /// streams differ, the distribution does not.
        /// </remarks>
        /// <param name="count">The number of operations.</param>
        /// <param name="insertFraction">The probability that an operation is an insert.</param>
        /// <param name="collisionFraction">The probability that an insert reuses an earlier key.</param>
        /// <param name="seed">The random seed.</param>
        /// <returns>The workload.</returns>
        public static WritesWorkload Generate(int count, double insertFraction, double collisionFraction, int seed)
        {
            ArgumentOutOfRangeException.ThrowIfNegative(count);

            var random = new Random(seed);
            var cells = new uint[checked(count * ColumnCount)];
            var isRemoval = new bool[count];
            for (var i = 0; i < count; i++)
            {
                var offset = i * ColumnCount;

                // The draws happen in egglog's order: the insert coin, then (for an insert) the collision coin, each
                // before the emptiness test that guards it.
                if (NextBool(random, insertFraction) == false && i > 0)
                {
                    Array.Copy(cells, random.Next(i) * ColumnCount, cells, offset, KeyCount);
                    isRemoval[i] = true;
                }
                else if (NextBool(random, collisionFraction) && i > 0)
                {
                    var source = random.Next(i) * ColumnCount;
                    FillRandom(random, cells.AsSpan(offset, ColumnCount));
                    Array.Copy(cells, source, cells, offset, KeyCount);
                }
                else
                {
                    FillRandom(random, cells.AsSpan(offset, ColumnCount));
                }
            }

            return new WritesWorkload(cells, isRemoval);
        }

        /// <summary>
        /// Gets the number of live keys a table holds after merging this workload in <paramref name="merges"/> epochs of
        /// <c>ceil(Count / merges)</c> operations, from a fresh table: a reference model of
        /// <see cref="SortedWritesTable.Merge"/>, which applies every staged removal of an epoch before any of its
        /// inserts. Used to check that a benchmark iteration did its work. O(Count) with a hash set.
        /// </summary>
        /// <param name="merges">The number of epochs.</param>
        /// <returns>The live key count.</returns>
        public int CountLiveKeys(int merges)
        {
            ArgumentOutOfRangeException.ThrowIfLessThan(merges, 1);

            var live = new HashSet<(uint, uint, uint)>();
            var epochSize = EpochSize(merges);
            for (var start = 0; start < Count; start += epochSize)
            {
                var end = Math.Min(Count, start + epochSize);
                for (var i = start; i < end; i++)
                    if (IsRemoval[i])
                        live.Remove(KeyAt(i));

                for (var i = start; i < end; i++)
                    if (IsRemoval[i] == false)
                        live.Add(KeyAt(i));
            }

            return live.Count;
        }

        /// <summary>
        /// Gets the number of operations per epoch when the workload is merged in <paramref name="merges"/> epochs:
        /// egglog's <c>workload.len().next_multiple_of(n_merges) / n_merges</c>.
        /// </summary>
        /// <param name="merges">The number of epochs; at least one.</param>
        /// <returns>The epoch size; at least one.</returns>
        public int EpochSize(int merges) => Math.Max(1, (int)(((long)Count + merges - 1) / merges));

        /// <summary>
        /// Gets the key of operation <paramref name="index"/> as a tuple.
        /// </summary>
        /// <param name="index">The operation index.</param>
        /// <returns>The key.</returns>
        (uint, uint, uint) KeyAt(int index)
        {
            var offset = index * ColumnCount;
            return (Cells[offset], Cells[offset + 1], Cells[offset + 2]);
        }

        /// <summary>
        /// Draws <c>true</c> with probability <paramref name="probability"/>: rand's <c>random_bool</c>.
        /// </summary>
        /// <param name="random">The random source.</param>
        /// <param name="probability">The probability, in [0, 1].</param>
        /// <returns>The draw.</returns>
        static bool NextBool(Random random, double probability) => random.NextDouble() < probability;

        /// <summary>
        /// Fills <paramref name="row"/> with values uniform in [0, <see cref="uint.MaxValue"/>): egglog's
        /// <c>random_row</c>, which excludes the stale marker.
        /// </summary>
        /// <param name="random">The random source.</param>
        /// <param name="row">The cells to fill.</param>
        static void FillRandom(Random random, Span<uint> row)
        {
            for (var i = 0; i < row.Length; i++)
                row[i] = (uint)random.NextInt64(0, uint.MaxValue);
        }

    }

}
